import {SURFACE_TYPES,surfaceLimits} from './surfaces.js';
import {icon,esc,fmt} from './assets.js';
export function surfaceThumb(kind){const terrace=kind==='terrace';return `<svg viewBox="0 0 140 100" aria-hidden="true"><ellipse cx="72" cy="79" rx="56" ry="12" fill="#526a3920"/>${!terrace?'<path d="M26 51v29m77-41v29m20-14v26" stroke="#7f9277" stroke-width="5"/>':''}<path d="m18 43 66-25 44 26-65 29Z" fill="${terrace?'#c4ac83':'#d4bc94'}" stroke="#9b896a" stroke-width="1.3"/><path d="m18 43 45 26 65-25v7L63 77 18 50Z" fill="#ae936a"/>${Array.from({length:7},(_,i)=>`<path d="m${26+i*8} ${40-i*3} 44 26" stroke="#ac946c" stroke-width=".9" opacity=".7"/>`).join('')}${!terrace?'<path d="M20 42V29l64-25 43 26v13M34 24v14M51 18v14M67 12v14M98 12v13M113 21v13" fill="none" stroke="#7b8f6a" stroke-width="2.1"/>':'<path d="m103 38 10 6v9l-10-6Z" fill="#9b8464"/><ellipse cx="108" cy="36" rx="9" ry="10" fill="#7e9a67"/>'}</svg>`;}
export function surfaceCards(query=''){const entries=Object.entries(SURFACE_TYPES).filter(([,k])=>k.name.toLocaleLowerCase('fr').includes(query.toLocaleLowerCase('fr')));return `<p class="m-help-text surface-intro">Des planchers ouverts, indépendants des pièces. Ils ne comptent pas comme habitation.</p><div class="catalog-grid surface-cards">${entries.map(([key,k])=>`<button class="catalog-card" data-add-surface="${key}"><span class="thumb">${surfaceThumb(key)}</span><span class="card-name">${k.name}</span><span class="card-size">${k.description}</span><span class="card-plus">${icon('plus')}</span></button>`).join('')}</div>${!entries.length?'<p class="empty">Aucune surface trouvée.</p>':''}`;}
export function surfaceFields({s,o,field,select}){
 const bounds=surfaceLimits(s,o),f=(label,key,min,max)=>field(label,'@'+key,'m','.1',min,max,o[key]);
 const basic=`<label class="field m-name-field"><span>Nom de la surface</span><input data-entity-field="name" value="${esc(o.name)}" maxlength="50"></label><div class="fields">${f('Largeur','w',.6,bounds.maxW)}${f('Longueur','l',.6,bounds.maxL)}</div><div class="fields one">${select('Sur quel niveau ?','@levelId',s.levels.filter(l=>o.kind==='terrace'||l.kind!=='ground').map(l=>[l.id,l.name]),o.levelId)}</div>`;
 const position=`<p class="m-help-text">${o.kind==='terrace'?'Une terrasse peut dépasser le bâtiment. Une position négative la place à gauche ou en haut du plan.':'Placez ce plancher où vous voulez à l’intérieur du bâtiment.'}</p><div class="fields">${f('Position X','x',bounds.minX,bounds.maxX)}${f('Position Y','y',bounds.minY,bounds.maxY)}</div>`;
 const details=`<div class="fields one">${select('Revêtement','@finish',[['wood','Lames de bois'],['concrete','Béton clair']],o.finish)}${select('Garde-corps sur les bords libres','@railing',[['true','Oui'],['false','Non']],String(o.railing))}</div><p class="m-help-text">${fmt(o.w*o.l)} m² de surface ouverte. L’altitude et l’épaisseur du plancher suivent le niveau choisi.</p><button class="btn full" data-action="level-settings">${icon('layers')}Régler l’altitude du niveau</button>${s.levels.find(l=>l.id===o.levelId)?.kind!=='ground'?`<button class="btn full" data-action="stairs">${icon('stairs')}Ajouter un escalier d’accès</button>`:''}`;
 return{basic,position,details};
}
